structure ValuationSpectrum (A : Type*) [CommRing A] extends ValuativeRel A

namespace ValuationSpectrum

variable {A : Type*} [CommRing A]

def basicOpen (f s : A) : Set (ValuationSpectrum A) :=
  { v | v.vle f s ∧ ¬ v.vle s 0 }

instance instTopologicalSpace : TopologicalSpace (ValuationSpectrum A) :=
  TopologicalSpace.generateFrom { U | ∃ f s : A, U = basicOpen f s }

def IsContinuous [TopologicalSpace A] (v : ValuationSpectrum A) : Prop :=
  letI : ValuativeRel A := v.toValuativeRel
  ∀ γ : (ValuativeRel.ValueGroupWithZero A), IsOpen { a : A | ValuativeRel.valuation A a < γ }

def Cont (A : Type*) [CommRing A] [TopologicalSpace A] : Set (ValuationSpectrum A) :=
  { v : ValuationSpectrum A | v.IsContinuous }

class PlusSubring (A : Type*) [CommRing A] where
  toSubring : Subring A

def ringPlus (A : Type*) [CommRing A] [PlusSubring A] : Subring A :=
  PlusSubring.toSubring

variable [TopologicalSpace A]

def Spa (A : Type*) [CommRing A] [TopologicalSpace A] (Aplus : Subring A) : Set (ValuationSpectrum A) :=
  { v ∈ Cont A | ∀ f ∈ Aplus, v.vle f 1 }

variable [PlusSubring A]

def rationalOpen (T : Finset A) (s : A) : Set (ValuationSpectrum A) :=
  { v ∈ Spa A (ringPlus A) | (∀ t ∈ T, v.vle t s) ∧ ¬ v.vle s 0 }

end ValuationSpectrum

